      "activity_name": "Analyze protos/utils usage and dependencies",
      "activity_description": "Identify all references to protos/utils in the codebase, including generated code, utilities, and extensions.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2.2",
      "activity_name": "Create protoutils package and move code",
      "activity_description": "Create new top-level package 'protoutils' and move the utils code, adjusting package structure.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2.3",
      "activity_name": "Update imports across codebase",
      "activity_description": "Update all import statements in the codebase to reference the new protoutils package.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2.4",
      "activity_name": "Update build scripts",
      "activity_description": "Modify build scripts (Makefile, Bazel, etc.) to include the new protoutils package.",
      "most_likely_effort": 8
